bounded_host_request.command:
set -euo pipefail
mapfile -t ids < <(docker ps -q --filter label=com.docker.compose.service=gaybbs)
test "${#ids[@]}" -eq 1 || exit 60
cid="${ids[0]}"
docker exec "$cid" test -r /run/secrets/bot_token || exit 61
docker exec "$cid" test -r /run/secrets/bug_report_recipient || exit 62
docker exec "$cid" node --version >/dev/null || exit 63
docker exec -i "$cid" node --import /app/preload/telegram-ipv4-preload.mjs --input-type=module <<'JS'
import {readFileSync} from "node:fs";
const token=readFileSync("/run/secrets/bot_token","utf8").trim();
const target=readFileSync("/run/secrets/bug_report_recipient","utf8").trim();
if(!token||!/^[0-9]+$/.test(target))process.exit(64);
console.log("NODE_SECRET_PREFLIGHT=PASS");
JS
echo PRIVATE_OPERATOR_SEND_PREREQUISITES=PASS
